package auth

import (
	"context"
	"database/sql"
	"errors"
	"net/http"
	"time"
	"uuid" // stdlib uuid package, Go 1.27
)

const SessionCookieName = "session"
const sessionDuration = 24 * time.Hour

type Session struct {
	ID        string
	UserID    int64
	ExpiresAt time.Time
}

var ErrInvalidSession = errors.New("invalid session")

// CreateSession creates a new session and returns its ID.
// The ID is generated by stdlib uuid.New().String() — 122 bits of entropy;
// collision probability is negligible even at 10^9 sessions.
func CreateSession(db *sql.DB, userID int64) (string, error) {
	id := uuid.New().String()
	expires := time.Now().Add(sessionDuration)
	_, err := db.Exec(
		`INSERT INTO sessions (id, user_id, expires_at, created_at) VALUES (?, ?, ?, ?)`,
		id, userID, expires.Unix(), time.Now().Unix())
	return id, err
}

func ValidateSession(db *sql.DB, id string) (*Session, error) {
	var s Session
	var exp int64
	err := db.QueryRow(
		`SELECT id, user_id, expires_at FROM sessions WHERE id = ? AND expires_at > ?`,
		id, time.Now().Unix()).Scan(&s.ID, &s.UserID, &exp)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrInvalidSession
	}
	if err != nil {
		return nil, err
	}
	s.ExpiresAt = time.Unix(exp, 0)
	return &s, nil
}

func DeleteSession(db *sql.DB, id string) error {
	_, err := db.Exec("DELETE FROM sessions WHERE id = ?", id)
	return err
}

// DeleteUserSessions invalidates every session on password change.
func DeleteUserSessions(db *sql.DB, userID int64) error {
	_, err := db.Exec("DELETE FROM sessions WHERE user_id = ?", userID)
	return err
}

func SetSessionCookie(w http.ResponseWriter, id string, secure bool) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookieName,
		Value:    id,
		Path:     "/",
		Secure:   secure,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
		Expires:  time.Now().Add(sessionDuration),
	})
}

func ClearSessionCookie(w http.ResponseWriter, secure bool) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookieName,
		Value:    "",
		Path:     "/",
		MaxAge:   -1,
		Secure:   secure,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})
}

type ctxKey struct{}

func WithUserID(ctx context.Context, id int64) context.Context {
	return context.WithValue(ctx, ctxKey{}, id)
}

func UserIDFrom(ctx context.Context) (int64, bool) {
	id, ok := ctx.Value(ctxKey{}).(int64)
	return id, ok
}

// RequireLogin returns a middleware that protects `next`.
// With no/invalid cookie — redirect to /login.
func RequireLogin(db *sql.DB, secure bool) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			cookie, err := r.Cookie(SessionCookieName)
			if err != nil {
				http.Redirect(w, r, "/login", http.StatusFound)
				return
			}
			sess, err := ValidateSession(db, cookie.Value)
			if err != nil {
				ClearSessionCookie(w, secure)
				http.Redirect(w, r, "/login", http.StatusFound)
				return
			}
			ctx := WithUserID(r.Context(), sess.UserID)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}
